package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.io.*;import org.json.*;
/** Offline measurement of the actual native components; does not send messages or upload media. */
public class PopupCatalogAudit extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 Object call(Object a,String n,Class<?>[] t,Object...v)throws Exception{Method m=a.getClass().getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(a,v);}
 void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 int dp(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}
 TextView find(View v,String value){if(v instanceof TextView&&((TextView)v).getText().toString().equals(value))return(TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=find(g.getChildAt(i),value);if(t!=null)return t;}}return null;}
 EditText input(View v){if(v instanceof EditText)return(EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=input(g.getChildAt(i));if(e!=null)return e;}}return null;}
 String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)s+="\n"+text(g.getChildAt(i));}return s;}
 void shot(Activity a,String n)throws Exception{waitForIdleSync();Thread.sleep(200);try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),n))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}}
 public void onStart(){Bundle result=new Bundle();try{
 getTargetContext().getSharedPreferences("native_setup",0).edit().putBoolean("asked_v1",true).commit();Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(800);
 final String[] icons=new String[]{"circle_check","circle_help","clapperboard","close","copy","eye_off","flag","globe","image","log_out","mail","map_pin","mic","newspaper","pencil","radio","send","settings","share_2","shield_check","trash","user_round","users_round","video","wand"};
 final Class<?> sheet=getTargetContext().getClassLoader().loadClass("app.kinnect.live.Sheet");final Constructor<?> ctor=sheet.getDeclaredConstructor(Context.class);ctor.setAccessible(true);
 for(int offset=0;offset<icons.length;offset+=6){final String[] group=java.util.Arrays.copyOfRange(icons,offset,Math.min(offset+6,icons.length));final Dialog[] dialog={null};
 runOnMainSync(()->{try{Object builder=ctor.newInstance(a);call(builder,"setTitle",new Class[]{CharSequence.class},"Popup icon audit");call(builder,"setItemIcons",new Class[]{String[].class},(Object)group);call(builder,"setItems",new Class[]{CharSequence[].class,DialogInterface.OnClickListener.class},(Object)group,(DialogInterface.OnClickListener)(d,w)->{});dialog[0]=(Dialog)call(builder,"show",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(100);
 runOnMainSync(()->{for(String name:group){TextView t=find(dialog[0].getWindow().getDecorView(),name);check(t!=null,"Missing popup label");ViewGroup row=(ViewGroup)t.getParent();check(row.getChildAt(0)instanceof ImageView,"Missing popup icon: "+name);ImageView icon=(ImageView)row.getChildAt(0);Bitmap b=Bitmap.createBitmap(icon.getWidth(),icon.getHeight(),Bitmap.Config.ARGB_8888);icon.draw(new Canvas(b));int count=0;for(int x=0;x<b.getWidth();x++)for(int y=0;y<b.getHeight();y++)if((b.getPixel(x,y)>>>24)>20)count++;b.recycle();check(count>6,"Blank popup icon: "+name);}});runOnMainSync(()->dialog[0].dismiss());
 }
 final Dialog[] fallback={null};runOnMainSync(()->{try{Object builder=ctor.newInstance(a);call(builder,"setItems",new Class[]{CharSequence[].class,DialogInterface.OnClickListener.class},(Object)new String[]{"Unspecified choice"},(DialogInterface.OnClickListener)(d,w)->{});fallback[0]=(Dialog)call(builder,"show",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();runOnMainSync(()->{TextView t=find(fallback[0].getWindow().getDecorView(),"Unspecified choice");check(((ViewGroup)t.getParent()).getChildAt(0)instanceof ImageView,"Plain choice fallback missing");fallback[0].dismiss();a.finish();});result.putString("result","PASS: "+icons.length+" popup icon names from actual source arrays visibly render in real Sheet rows; plain selection fallback present. Checkbox selections retain checkbox controls. No actions sent.");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}
